native-vs-cross-platform-decision.code:
CRITERIA = [
    ("offline-write-survival", 5, True),
    ("secure-token-storage", 4, True),
    ("background-lifecycle-control", 4, False),
    ("team-velocity", 3, False),
    ("store-review-risk", 2, False),
]
HARD_FLOOR = 4
OPTIONS = {
    "native-kotlin-swift": {"offline-write-survival": 5, "secure-token-storage": 5, "background-lifecycle-control": 5, "team-velocity": 2, "store-review-risk": 4},
    "react-native": {"offline-write-survival": 4, "secure-token-storage": 4, "background-lifecycle-control": 3, "team-velocity": 5, "store-review-risk": 4},
    "pwa": {"offline-write-survival": 2, "secure-token-storage": 1, "background-lifecycle-control": 1, "team-velocity": 5, "store-review-risk": 5},
}


def evaluate(option, scores):
    for name, weight, hard in CRITERIA:
        if name not in scores:
            raise ValueError(f"{option}: no score for {name} — decide with data, not defaults")
    for name, weight, hard in CRITERIA:
        if hard and scores[name] < HARD_FLOOR:
            return None, f"{name}={scores[name]}"
    total = sum(scores[name] * weight for name, weight, hard in CRITERIA)
    return total, ""


qualified = []
for option, scores in OPTIONS.items():
    total, reason = evaluate(option, scores)
    if total is None:
        print(f"{option}: DISQUALIFIED hard constraint {reason} < floor {HARD_FLOOR}")
    else:
        qualified.append((total, option))
        print(f"{option}: qualified weighted={total}")

qualified.sort(reverse=True)
winner_total, winner = qualified[0]
margin = winner_total - qualified[1][0]
print(f"decision: {winner} by {margin} weighted points over {len(qualified) - 1} qualified rival(s)")
print(f"invalidation: revisit if the offline requirement is dropped or any winner hard score falls below {HARD_FLOOR}")

navigation-and-state-boundaries.code:
EVENT_ORDER = ["background", "process-death", "offline-reconnect"]
SURVIVES = {
    "route-local": {"background"},
    "viewmodel": {"background"},
    "saved-state": {"background", "process-death"},
    "durable-store": {"background", "process-death", "offline-reconnect"},
}
COST = {"route-local": 0, "viewmodel": 1, "saved-state": 2, "durable-store": 3}
FIELDS = [
    ("scroll_position", {"background"}, "route-local", 0),
    ("active_section", {"background", "process-death"}, "viewmodel", 2),
    ("inspection_draft", {"background", "process-death", "offline-reconnect"}, "viewmodel", 34),
    ("signature_blob", {"background", "process-death"}, "route-local", 3),
    ("photo_queue", {"background", "process-death", "offline-reconnect"}, "durable-store", 6),
]


def cheapest_safe(needs):
    candidates = [p for p in SURVIVES if needs <= SURVIVES[p]]
    return min(candidates, key=lambda p: COST[p])


at_risk = 0
misplaced = 0
conflict_note_needed = False
for name, needs, current, minutes in FIELDS:
    if needs <= SURVIVES[current]:
        if "offline-reconnect" in needs:
            conflict_note_needed = True
        print(f"{name} [{current}]: ok")
    else:
        misplaced += 1
        at_risk += minutes
        dies_at = next(e for e in EVENT_ORDER if e in needs and e not in SURVIVES[current])
        target = cheapest_safe(needs)
        if "offline-reconnect" in needs:
            conflict_note_needed = True
        print(f"{name} [{current}]: MISPLACED dies at {dies_at} -> move to {target} ({minutes} min at risk)")

print(f"audit: {misplaced} of {len(FIELDS)} fields misplaced, {at_risk} min of field work at risk")
if conflict_note_needed:
    print("note: every durable-store field needs a conflict policy for offline-reconnect — survival without one is just a slower overwrite")

conflict-resolution.code:
BASE = {"status": "open", "notes": "", "gps": "41.88,-87.63", "assignee": "sam"}
LOCAL = {"status": "complete", "notes": "valve corroded, washer replaced", "gps": "41.8803,-87.6329", "assignee": "sam"}
SERVER = {"status": "cancelled", "notes": "", "gps": "41.88,-87.63", "assignee": "riley"}
RULES = {"status": "manual", "notes": "local-wins", "gps": "local-wins", "assignee": "server-wins"}

merged = {}
queue = []
traces = []
for field in BASE:
    b, l, s = BASE[field], LOCAL[field], SERVER[field]
    local_changed = l != b
    server_changed = s != b
    if not local_changed and not server_changed:
        merged[field] = b
        outcome = "unchanged"
    elif local_changed and not server_changed:
        merged[field] = l
        outcome = "local-only -> take local"
    elif server_changed and not local_changed:
        merged[field] = s
        outcome = "server-only -> take server"
    else:
        rule = RULES[field]
        if rule == "manual":
            merged[field] = b
            queue.append(field)
            outcome = "BOTH changed -> manual queue (base kept)"
        elif rule == "local-wins":
            merged[field] = l
            traces.append((field, s))
            outcome = "BOTH changed -> rule local-wins"
        else:
            merged[field] = s
            traces.append((field, l))
            outcome = "BOTH changed -> rule server-wins"
    print(f"{field}: {outcome} = {merged[field]!r}")

print(f"merged: {merged}")
print(f"manual queue: {queue} (candidates attached: local={LOCAL[queue[0]]!r} server={SERVER[queue[0]]!r})")
print(f"auto-resolved conflicts traced: {len(traces)} — every losing value is queryable, none vanished")

secure-token-storage.code:
TOKENS = [
    ("access-token", "api-short-lived", "memory"),
    ("refresh-token", "session-minting", "shared-prefs-plaintext"),
    ("push-token", "routing", "app-file"),
    ("biometric-unlock-key", "local-unlock", "keystore-hardware"),
]
ACCEPT = {
    "api-short-lived": {"memory", "keychain-device-unlocked", "keystore-hardware"},
    "session-minting": {"keystore-hardware"},
    "routing": {"app-file", "keychain-device-unlocked", "keystore-hardware"},
    "local-unlock": {"keystore-hardware"},
}

crit = high = ok = 0
crit_minting = False
for name, klass, store in TOKENS:
    if store in ACCEPT[klass]:
        ok += 1
        print(f"{name} [{klass}] in {store}: OK")
    else:
        sev = "CRITICAL" if "plaintext" in store else "HIGH"
        if sev == "CRITICAL":
            crit += 1
            if klass == "session-minting":
                crit_minting = True
        else:
            high += 1
        required = " or ".join(sorted(ACCEPT[klass]))
        print(f"{name} [{klass}] in {store}: {sev} — move to {required}")

print(f"audit: {crit} critical, {high} high, {ok} ok across {len(TOKENS)} credentials")
if crit_minting:
    print("blast radius: a plaintext session-minting token turns one device backup into a 90-day account takeover")

