FALLBACKS = {
    "camera": "attach from gallery or add text note",
    "location": "manual site-code entry",
    "notifications": "in-app inbox badge",
}
EVENTS = [
    ("request-at-point-of-use", "location", "denied"),
    ("use-attempt", "location", None),
    ("request-at-point-of-use", "camera", "granted"),
    ("use-attempt", "camera", None),
    ("os-auto-revoke", "camera", "90 days idle"),
    ("use-attempt", "camera", None),
    ("request-at-point-of-use", "notifications", "granted"),
]

state = {p: "undetermined" for p in FALLBACKS}
fallbacks_used = 0
for kind, perm, arg in EVENTS:
    if kind == "request-at-point-of-use":
        state[perm] = arg
        print(f"{perm}: requested at point of use -> {arg}")
    elif kind == "os-auto-revoke":
        state[perm] = "revoked"
        print(f"{perm}: OS revoked ({arg}) — no callback fired, state only visible at next use")
    else:
        if state[perm] == "granted":
            print(f"{perm}: use ok")
        else:
            fallbacks_used += 1
            print(f"{perm}: {state[perm]} at use — fallback engaged: {FALLBACKS[perm]} (job continues)")

print(f"day complete: {fallbacks_used} capability losses absorbed by fallbacks, 0 jobs blocked, 0 crashes")
print(f"the core job never depended on a permission — {len(FALLBACKS)} declared fallbacks made denial a UX event, not an outage")

privacy-safe-telemetry.code:
import hashlib

POLICY = {"customer_name": "drop", "address": "drop", "customer_id": "hash",
          "gps": "coarsen", "job_type": "keep", "duration_min": "keep", "outcome": "keep"}
PII_KEYS = {"customer_name", "address"}
EVENTS = [
    {"event": "job_completed", "customer_name": "R. Alvarez", "address": "1180 W Monroe St",
     "customer_id": "cus_4417", "gps": (41.881832, -87.653321), "job_type": "hvac-inspection",
     "duration_min": 44, "outcome": "pass"},
    {"event": "job_completed", "customer_name": "T. Okafor", "address": "77 Elm Ct",
     "customer_id": "cus_9022", "gps": (41.90211, -87.62894), "job_type": "valve-repair",
     "duration_min": 71, "outcome": "flagged"},
]

queue = []
dropped = hashed = 0
for raw in EVENTS:
    out = {"event": raw["event"]}
    for key, value in raw.items():
        if key == "event":
            continue
        rule = POLICY[key]
        if rule == "drop":
            dropped += 1
        elif rule == "hash":
            hashed += 1
            out[key] = hashlib.sha256(value.encode()).hexdigest()[:10]
        elif rule == "coarsen":
            out[key] = f"{round(value[0], 2)},{round(value[1], 2)}"
        else:
            out[key] = value
    queue.append(out)
    print(f"queued {out['event']}: id={out['customer_id']} gps={out['gps']} job={out['job_type']} dur={out['duration_min']} outcome={out['outcome']}")

leaks = sum(1 for e in queue for k in e if k in PII_KEYS)
print(f"redacted at creation: {dropped} fields dropped, {hashed} hashed, {len(queue)} events queued")
print(f"PII scan of durable queue: {leaks} raw identity fields found — the disk never knew the names")

