ELEMENTS = [
    ("btn_complete", "button", "Complete job", "enabled", 1, 56),
    ("btn_photo", "button", "", "enabled", 2, 44),
    ("btn_sync", "button", "", "enabled", 4, 40),
    ("toggle_offline", "switch", "Offline mode", "", 3, 52),
    ("banner_conflict", "alert", "Sync conflict on work order 118", "live-region", 5, 64),
]

issues = 0
for eid, role, name, state, focus, dp in ELEMENTS:
    problems = []
    if not name:
        problems.append(f"missing name (reads as just '{role}')")
    if role == "switch" and not state:
        problems.append("state not exposed (on/off unknown)")
    if dp < 48:
        problems.append(f"touch target {dp}dp < 48dp")
    if problems:
        issues += len(problems)
        print(f"{eid}: FAIL — {'; '.join(problems)}")
    else:
        print(f"{eid}: pass")

inversions = 0
max_seen = 0
for eid, role, name, state, focus, dp in ELEMENTS:
    if focus < max_seen:
        inversions += 1
        print(f"focus jump: {eid} (focus {focus}) is visited AFTER focus {max_seen} — reader path deviates from reading order")
    max_seen = max(max_seen, focus)

print(f"audit: {issues} element issues + {inversions} focus inversion(s) across {len(ELEMENTS)} elements")
print("the walk test still governs: fix these, then complete the job eyes-free before calling it done")

gesture-and-input-constraints.code:
PIPELINES = {
    "act-first": ["mutate-ui", "debounce-500ms", "persist-intent", "sync"],
    "journal-first": ["persist-intent", "mutate-ui", "sync"],
}
INTERRUPTS = [
    ("phone call kills app after 1 stage", 1),
    ("process death after 2 stages", 2),
    ("no interruption", 99),
]

scores = {}
for name, stages in PIPELINES.items():
    survived = 0
    for label, n in INTERRUPTS:
        done = stages[:n] if n < 99 else stages
        ok = "persist-intent" in done
        if ok:
            survived += 1
        state = "SURVIVED" if ok else f"LOST (journal never ran; completed: {', '.join(done)})"
        print(f"{name} / {label}: {state}")
    scores[name] = survived
    print(f"{name}: intent survived {survived}/{len(INTERRUPTS)} interruption scenarios")

best = max(scores, key=lambda k: scores[k])
print(f"verdict: {best} — durability BEFORE reaction is the only ordering that survives the field")

post-release-incident-loop.code:
INCIDENTS = [
    ("INC-1 misaligned checkout button", 4000, 0, False, False, True),
    ("INC-2 silent overwrite on reconnect", 60, 0, True, True, False),
    ("INC-3 crash on notification tap", 900, 900, False, False, True),
]


def severity(users, crashes, data_loss, irreversible, workaround):
    score = min(users, 1000) / 100
    if data_loss:
        score += 40
    if irreversible:
        score += 20
    if crashes > 0:
        score += 25
    if workaround:
        score -= 5
    return score


def lane(score):
    if score >= 60:
        return "halt rollout + hotfix now"
    if score >= 25:
        return "hotfix next release"
    return "backlog"


scored = []
for inc_id, users, crashes, data_loss, irreversible, workaround in INCIDENTS:
    s = severity(users, crashes, data_loss, irreversible, workaround)
    scored.append((s, inc_id))

scored.sort(reverse=True)
for s, inc_id in scored:
    print(f"{inc_id}: severity {s} -> {lane(s)}")

by_volume = max(INCIDENTS, key=lambda i: i[1])[0]
lowest = scored[-1][1]
print(f"volume-only sort would work {by_volume} first and rank {scored[0][1]} last — the harm-priced queue inverts it")
print(f"the data-loss incident reached the top with {INCIDENTS[1][1]} users — severity priced what cannot be given back")
